// Payment Processing Service (code/payment.js)
// Converts integer minor units (cents) into whole major currency units (dollars).
function processPayment(amountMinor) {
  // BUG: entered 100 minor units charges 100 dollars instead of dividing by 100 and rounding down!
  return amountMinor;
}

console.log('100 minor ->', processPayment(100));
console.log('199 minor ->', processPayment(199));
console.log('250 minor ->', processPayment(250));
